head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldinf10700";
scwin.std_cd_apct_tp_cd = null;
scwin.reg_button = null;
scwin.blurHandled = false;
scwin.dmenus = undefined;
scwin.cntrIsoCd = undefined;

///////// 2. 초기화 영역 /////////
// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — cfiCdGroupList, stdCdApctTpCdList, applId, acntNo, feeProcsStatCd

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "rd_group", fn: function(){ return (!(String(((dma_pageContext.get("cfiCdGroupList") ?? "")) == null ? '' : ((dma_pageContext.get("cfiCdGroupList") ?? ""))).length === 0)); } }, { id: "rd_stdCdApctTpCd", fn: function(){ return (!(String(((dma_pageContext.get("stdCdApctTpCdList") ?? "")) == null ? '' : ((dma_pageContext.get("stdCdApctTpCdList") ?? ""))).length === 0)); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        let ok;
        // 조건식이 미해결 값(unresolved throw)을 읽는 자리는 그 바인드만 건너뛴다 — 공급사 산출의 바인드별 격리 유지
        try { ok = !!b.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); return; }
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_datefmt_cal_isuDd
 * @description 초기화 — datefmt cal isu Dd
 * @returns {void}
 * @hidden N
 */
scwin.init_datefmt_cal_isuDd = function () { $c.date.checkCalendarFormat("cal_isuDd", "yyyyMMdd"); };

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_pageBody = async function () {
    try {
        if ((String(((dma_pageContext.get("applId") ?? "")) == null ? '' : ((dma_pageContext.get("applId") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("applId") ?? "")) == null ? '' : ((dma_pageContext.get("applId") ?? "")))) !== '') {
            await scwin.beforIsur((String(((dma_pageContext.get("applId") ?? "")) == null ? '' : ((dma_pageContext.get("applId") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("applId") ?? "")) == null ? '' : ((dma_pageContext.get("applId") ?? "")))));
            $c.util.getComponent("ipt_returnApplId").setValue((String(((dma_pageContext.get("applId") ?? "")) == null ? '' : ((dma_pageContext.get("applId") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("applId") ?? "")) == null ? '' : ((dma_pageContext.get("applId") ?? "")))));
            $c.util.getComponent("ipt_asumAcntNo").setValue((String(((dma_pageContext.get("acntNo") ?? "")) == null ? '' : ((dma_pageContext.get("acntNo") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("acntNo") ?? "")) == null ? '' : ((dma_pageContext.get("acntNo") ?? "")))));
            $c.util.getComponent("ipt_stdCdGrntFeeProcsStatCd").setValue((String(((dma_pageContext.get("feeProcsStatCd") ?? "")) == null ? '' : ((dma_pageContext.get("feeProcsStatCd") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("feeProcsStatCd") ?? "")) == null ? '' : ((dma_pageContext.get("feeProcsStatCd") ?? "")))));
        }
        $('input[name=group][value=E]').attr("checked", true);
        scwin.chg_group($("#group_E"));

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldinf10700.onpageload' }); }
};

/**
 * @method
 * @name init_loadList
 * @description 초기 목록 조회 — as-is 는 진입 자체가 조회였다
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_loadList = async function () {
    // 초기 목록 — as-is 는 진입 자체가 조회였다(근거: self_submit). 진입점 합성이 이 단계를 잇는다.
    await scwin.tx_fnRegSave();
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

try { scwin.dmenus ={
        "bmenu":2
        ,"mmenu":7
    }; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldinf10700' }); }

try { scwin.cntrIsoCd =$c.util.getComponent("dma_ChkFormReq").get("cntrIsoCd"); } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldinf10700' }); }

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.std_cd_apct_tp_cd = $c.util.getComponent('std_cd_apct_tp_cd');
        scwin.reg_button = $c.util.getComponent('reg_button');
        scwin.init_conds();
        scwin.init_datefmt_cal_isuDd();
        await scwin.init_loadList();
        await scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldinf10700.onpageload' });
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_mpd_files_select_onclick
 * @description 「파일선택」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_mpd_files_select_onclick = function () {
    try { $c.util.onUploadClick($c.util.getComponent('mpd_files'));
    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldinf10700.btn_mpd_files_select_onclick' }); }
};

/**
 * @method
 * @name btn_mpd_files_del_onclick
 * @description 「삭제」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_mpd_files_del_onclick = async function () {
    try { const d = $c.util.getComponent('dlt_files'); const g = $c.util.getComponent('grd_mpd_files'); const u = $c.util.getComponent('mpd_files'); if (!d || !g) { return; } const idx = g.getCheckedIndex ? g.getCheckedIndex('CHK') : []; if (!idx || !idx.length) { return; } for (let i = idx.length - 1; i >= 0; i--) { try { const nm = d.getCellData(idx[i], 'FILE_NM'); if (u && u.removeFile) { u.removeFile(nm); } } catch (_e) { await $c.exception.handleError(_e, { notify: 'none', context: 'mpd_files.del' }); } } if (d.removeRows) { d.removeRows(idx); }
    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldinf10700.btn_mpd_files_del_onclick' }); }
};

