/**
 * @method
 * @name dataValidation
 * @description data Validation 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dataValidation = async function () {
    if ($c.str.getByteLength($c.util.getComponent('ipt_isurCd').getValue()) === 0) {
        await $c.win.alert("발행기관을 입력하세요.");
        $c.util.getComponent("ipt_isurCd").focus();  // 포커스 대상: 앞 문장이 가리키는 입력칸(as-is <폼>.<필드>.focus())
        return true;
    }
    if ($c.str.getByteLength($c.util.getComponent('ipt_basSecuIsuCd').getValue()) === 0) {
        if (!await $c.win.confirm("기초증권 표준코드를 입력하지 않았습니다.\n\n진행 하시겠습니까?")) {
            $c.util.getComponent("ipt_basSecuIsuCd").focus();
            return true;
        }
    }
    if ($c.str.getByteLength($c.util.getComponent('ipt_basSecuIsuNm').getValue()) === 0) {
        await $c.win.alert("기초증권 한글명을 입력하세요.");
        $c.util.getComponent("ipt_basSecuIsuNm").focus();
        return true;
    }
    if ($c.str.getByteLength($c.util.getComponent('ipt_basSecuIsuNm').getValue()) > 60) {
        await $c.win.alert("기초증권 한글명을 30자이내로 입력하세요.");
        $c.util.getComponent("ipt_basSecuIsuNm").focus();
        return true;
    }
    if ($c.str.getByteLength($c.util.getComponent('ipt_basSecuIsuEngNm').getValue()) === 0) {
        await $c.win.alert("기초증권 영문명을 입력하세요.");
        $c.util.getComponent("ipt_basSecuIsuEngNm").focus();
        return true;
    }
    if ($c.str.getByteLength($c.util.getComponent('ipt_basSecuIsuEngNm').getValue()) > 60) {
        await $c.win.alert("기초증권 영문명을 60자이내로 입력하세요.");
        $c.util.getComponent("ipt_basSecuIsuEngNm").focus();
        return true;
    }
    if ($c.str.getByteLength($c.util.getComponent('slc_basSecuKindCd').getValue()) === 0) {
        await $c.win.alert("기초증권 종류를 입력하세요.");
        $c.util.getComponent("slc_basSecuKindCd").focus();
        return true;
    }
    if ($c.util.getComponent('slc_basSecuKindCd').getValue() === '0') {
        if ($c.str.getByteLength($c.util.getComponent('slc_prefstkYn').getValue()) === 0) {
            await $c.win.alert("보통주/우선주를 선택하세요.");
            $c.util.getComponent("slc_prefstkYn").focus();
            return true;
        }
        if ($c.str.getByteLength($c.util.getComponent('slc_newstkKindCd').getValue()) === 0) {
            await $c.win.alert("신/구주 종류를 입력하세요.");
            $c.util.getComponent("slc_newstkKindCd").focus();
            return true;
        }
    }
    if ($c.str.getByteLength($c.util.getComponent('cal_isuDd').getValue()) === 0) {
        await $c.win.alert("발행일을 입력하세요.");
        $c.util.getComponent("cal_isuDd").focus();
        return true;
    }
    if ($c.str.getByteLength($c.util.getComponent('ipt_fornstkConvRto').getValue()) === 0) {
        await $c.win.alert("전환비율(원주)를 입력하세요.");
        $c.util.getComponent("ipt_fornstkConvRto").focus();
        return true;
    }
    if ($c.str.getByteLength($c.util.getComponent('ipt_drConvRto').getValue()) === 0) {
        await $c.win.alert("전환비율(DR)을 입력하세요.");
        $c.util.getComponent("ipt_drConvRto").focus();
        return true;
    }
    if ($c.str.getByteLength($c.util.getComponent('slc_currTpCd').getValue()) === 0) {
        await $c.win.alert("발행통화를 입력하세요.");
        document.curr_tp_cd.focus();
        return true;
    }
    if ($c.str.getByteLength($c.util.getComponent('ipt_nusualIsuCondContn').getValue()) > 0) {
        if ($c.util.getComponent('ipt_nusualIsuCondContn').getValue().indexOf("\t") > -1 || $c.util.getComponent('ipt_nusualIsuCondContn').getValue().indexOf("\n") > -1 || $c.util.getComponent('ipt_nusualIsuCondContn').getValue().indexOf("\r") > -1) {
            await $c.win.alert("특이발행조건에 '탭문자' 혹은 '개행문자'가 포함되어있습니다.\n다시 입력해 주십시오.");
            $("#ipt_nusualIsuCondContn").select();
            return true;
        }
    }
    if (!$('input[name=group]').is(":checked")) {
        await $c.win.alert("'그룹'을 선택하세요.");
        /* TODO Stage2: [sdd] 미실현 동작: set_focus (대상 미해석) — 전환 미완 */ /* unresolved-target intent:set_focus — {target}.focus({args}) */
        return true;
    }
    if ($c.str.getByteLength($c.util.getComponent('slc_attr01').getValue()) === 0) {
        await $c.win.alert("'1차속성'을 선택하세요.");
        $c.util.getComponent("slc_attr01").focus();
        return true;
    }
    if ($c.str.getByteLength($c.util.getComponent('slc_attr02').getValue()) === 0) {
        await $c.win.alert("'2차속성'을 선택하세요.");
        $c.util.getComponent("slc_attr02").focus();
        return true;
    }
    if ($c.str.getByteLength($c.util.getComponent('slc_attr03').getValue()) === 0) {
        await $c.win.alert("'3차속성'을 선택하세요.");
        $c.util.getComponent("slc_attr03").focus();
        return true;
    }
    if ($c.str.getByteLength($c.util.getComponent('slc_attr04').getValue()) === 0) {
        await $c.win.alert("'4차속성'을 선택하세요.");
        $c.util.getComponent("slc_attr04").focus();
        return true;
    }
    if ($("td#std_cd_apct_tp_cd input:checked").val() === "" || $("td#std_cd_apct_tp_cd input:checked").val() == null) {
        await $c.win.alert("신청인 소속구분을 선택하세요");
        scwin.std_cd_apct_tp_cd.focus();
        return true;
    }
    if ($c.str.getByteLength($c.util.getComponent('ipt_applComNm').getValue()) === 0) {
        await $c.win.alert("신청인 소속기관을 입력하세요");
        $c.util.getComponent("ipt_applComNm").focus();
        return true;
    }
    if ($c.str.getByteLength($c.util.getComponent('ipt_applComNm').getValue()) > 60) {
        await $c.win.alert("신청인 소속기관을 한글 30자, 영문 60자이내로 입력하세요");
        $c.util.getComponent("ipt_applComNm").focus();
        return true;
    }
    if ($c.str.getByteLength($c.util.getComponent('ipt_apctNm').getValue()) === 0) {
        await $c.win.alert("신청인 이름을  입력하세요");
        $c.util.getComponent("ipt_apctNm").focus();
        return true;
    }
    if ($c.str.getByteLength($c.util.getComponent('ipt_apctNm').getValue()) > 20) {
        await $c.win.alert("신청인이름을 한글 10자, 영문 20자이내로 입력하세요");
        $c.util.getComponent("ipt_apctNm").focus();
        return true;
    }
    if ($c.util.getComponent('ipt_cntrIsoCd').getValue() === '410') {
        if ($c.str.getByteLength($c.util.getComponent('ipt_apctTelNo1').getValue()) === 0) {
            await $c.win.alert("신청인 전화번호를  입력하세요");
            $c.util.getComponent("ipt_apctTelNo1").focus();
            return true;
        }
        if ($c.str.getByteLength($c.util.getComponent('ipt_apctTelNo2').getValue()) === 0) {
