    if ($c.str.getByteLength($c.util.getComponent('ipt_encrypApctEmail1').getValue() + $c.util.getComponent('ipt_encrypApctEmail2').getValue()) > 40) {
        await $c.win.alert("신청인 이메일을 한글 20자, 영문 40자이내로 입력하세요");
        $c.util.getComponent("ipt_encrypApctEmail1").focus();
        return true;
    }
    let encryp_apct_email = $c.util.getComponent('ipt_encrypApctEmail1').getValue() + "@" + $c.util.getComponent('ipt_encrypApctEmail2').getValue(); if (encryp_apct_email == null) { encryp_apct_email = ''; }
    if (!$c.str.isEmail(encryp_apct_email)) {
        await $c.win.alert("이메일 주소 형식이 아닙니다.");
        $c.util.getComponent("ipt_encrypApctEmail1").focus();
        return true;
    }
    return false;
};

/**
 * @method
 * @name Reset
 * @description Reset 처리
 * @returns {void}
 * @hidden N
 */
scwin.Reset = function () {
    const restInput = $("#conTable input:visible[name!=''][type='text']");
    for (let i = 0; i < restInput.length; i++) {
        $($(restInput)[i]).val("");
    }
    const restSelect = $("#conTable select:visible");
    for (let i = 0; i < restSelect.length; i++) {
        $($(restSelect)[i]).find('option:eq(0)').attr("selected", true);
    }
    const restRadio = $("#conTable input:visible[name!=''][type='radio']");
    for (let i = 0; i < restRadio.length; i++) {
        const radioName = $($(restRadio)[i]).attr("name");
        $('input[name=' + radioName + ']:eq(0)').attr("checked", true);
    }
    $('input[name=std_cd_apct_tp_cd]:eq(0)').attr("checked", true);
    $c.util.getComponent('ipt_applComNm').setValue("");
    $c.util.getComponent('ipt_apctNm').setValue("");
    $c.util.getComponent('dma_hiddenStore').set('ph01', "");
    $c.util.getComponent('dma_hiddenStore').set('ph02', "");
    $c.util.getComponent('dma_hiddenStore').set('ph03', "");
    $c.util.getComponent('dma_hiddenStore').set('fax01', "");
    $c.util.getComponent('dma_hiddenStore').set('fax02', "");
    $c.util.getComponent('dma_hiddenStore').set('fax03', "");
    $c.util.getComponent('dma_hiddenStore').set('email01', "");
    $c.util.getComponent('dma_hiddenStore').set('email02', "");
};

/**
 * @method
 * @name insName
 * @description ins Name 처리
 * @param {Object} obj 컴포넌트
 * @param {*} value value
 * @returns {void}
 * @hidden N
 */
scwin.insName = function (obj, value) {
    if (value === '') {
        $('#' + obj).val(value);
        return;
    }
    $('#' + obj).val(value + " KDR");
};

/**
 * @method
 * @name checkIsuCd
 * @description check Isu Cd 처리
 * @param {*} Name Name
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkIsuCd = async function (Name) {
    if (scwin.blurHandled) {
        return;
    }
    scwin.blurHandled = true;
    if ($c.str.getByteLength(Name.getValue()) > 0) {
        if ($c.str.getByteLength(Name.getValue()) !== 12) {
            await $c.win.alert("기초증권 표준코드가 올바르지 않습니다.(12자리).");
            Name.focus();
            setTimeout(function() {
                    scwin.blurHandled = false;
                }, 1000);
            return;
        }
        if (!await scwin.checkNumUpperEnglish(Name, '기초증권표준코드')) {
            return;
        }
    }
    setTimeout(function() {
            scwin.blurHandled = false;
        }, 100);
};

