                (($c.util.getComponent('slc_newstkKindCd')) && ($c.util.getComponent('slc_newstkKindCd')).setDisabled ? ($c.util.getComponent('slc_newstkKindCd')).setDisabled((true) === 'disabled' || (true) === 'readonly' || (true) === 'checked' ? true : (true)) : void 0);
