/**
 * @method
 * @name beforIsur
 * @description befor Isur 처리
 * @param {String} applId applId
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.beforIsur = async function (applId) {
    let isur_cd = $c.util.getComponent('ipt_isurCd').getValue(); if (isur_cd == null) { isur_cd = ''; }
    if (isur_cd === '') {
        await $c.win.alert("발행기관 코드를 입력해 주세요.");
        return;
    }
    const url = "/stdcd/dr.do?method=bfReturnReAppl";
    const params = "isur_cd=" + isur_cd + "&applId=" + applId + "&menuId=10700";
    $.post(url, params, async function(obj) {
            if (obj === '') {
                await $c.win.alert("직전입력분 자료가 없습니다.");
            } else {
                const jsonData = (typeof obj === "string" ? (typeof obj === "string" ? JSON.parse(obj) : obj) : obj);
                $c.util.getComponent('ipt_isuNm').setValue(jsonData.isu_nm);
                $c.util.getComponent('ipt_isuEngNm').setValue(jsonData.isu_eng_nm);
                $c.util.getComponent('ipt_basSecuIsuCd').setValue(jsonData.bas_secu_isu_cd);
                $c.util.getComponent('ipt_basSecuIsuNm').setValue(jsonData.bas_secu_isu_nm);
                $c.util.getComponent('ipt_basSecuIsuEngNm').setValue(jsonData.bas_secu_isu_eng_nm);
                $('#slc_basSecuKindCd').find('option[value="' + jsonData.bas_secu_kind_cd + '"]').attr("selected", true);
                $('#slc_prefstkYn').find('option[value="' + jsonData.prefstk_yn + '"]').attr("selected", true);
                $('#slc_newstkKindCd').find('option[value="' + jsonData.newstk_kind_cd + '"]').attr("selected", true);
                $c.util.getComponent('cal_isuDd').setValue($c.date.dateFormat(jsonData.isu_dd));
                $c.util.getComponent('ipt_fornstkConvRto').setValue(jsonData.fornstk_conv_rto);
                $c.util.getComponent('ipt_drConvRto').setValue(jsonData.dr_conv_rto);
                $('#slc_currTpCd').find('option[value="' + jsonData.curr_tp_cd + '"]').attr("selected", true);
                $('input[name=rd_domFornIsuTpCd][value="' + jsonData.dom_forn_isu_tp_cd + '"]').attr("checked", true);
                $c.util.getComponent('ipt_nusualIsuCondContn').setValue(jsonData.nusual_isu_cond_contn);
                const cfiCd = jsonData.cfi_cd.toString();
                $c.util.getComponent('slc_attr01').setValue(cfiCd.substring(2, 3));
                $c.util.getComponent('slc_attr02').setValue(cfiCd.substring(3, 4));
                $c.util.getComponent('slc_attr03').setValue(cfiCd.substring(4, 5));
                $c.util.getComponent('slc_attr04').setValue(cfiCd.substring(5, 6));
                scwin.chg_attr();
                $c.util.getComponent('ipt_fisnVal').setValue(jsonData.fisn_val);
                if (jsonData.std_cd_apct_tp_cd != null) {
                    const vl = jsonData.std_cd_apct_tp_cd.toString();
                    const tObj = $('input[name=std_cd_apct_tp_cd][value="' + vl + '"]');
                    if (tObj.length > 0) {
                        $(tObj)[0].checked = true;
                    }
                }
                if (jsonData.appl_com_nm != null) {
                    $c.util.getComponent('ipt_applComNm').setValue(jsonData.appl_com_nm.toString());
                }
                if (jsonData.apct_nm != null) {
                    $c.util.getComponent('ipt_apctNm').setValue(jsonData.apct_nm.toString());
                }
                if (jsonData.encryp_apct_email != null) {
                    const email = jsonData.encryp_apct_email.toString();
                    const emails = email.split("@");
                    if (emails.length > 0) {
                        $c.util.getComponent('ipt_encrypApctEmail1').setValue(emails[0]);
                    }
                    if (emails.length > 1) {
                        $c.util.getComponent('ipt_encrypApctEmail2').setValue(emails[1]);
                    }
                }
                if (jsonData.apct_tel_no != null) {
                    const tel = jsonData.apct_tel_no.toString();
                    const tels = tel.split("-");
                    if (tels.length > 0) {
                        $c.util.getComponent('ipt_apctTelNo1').setValue(tels[0]);
                    }
                    if (tels.length > 1) {
                        $c.util.getComponent('ipt_apctTelNo2').setValue(tels[1]);
                    }
                    if (tels.length > 2) {
                        $c.util.getComponent('ipt_apctTelNo3').setValue(tels[2]);
                    }
                }
                if (jsonData.apct_fax_no != null) {
                    const fax = jsonData.apct_fax_no.toString();
                    const faxs = fax.split("-");
                    if (faxs.length > 0) {
                        $c.util.getComponent('ipt_apctFaxNo1').setValue(faxs[0]);
                    }
                    if (faxs.length > 1) {
                        $c.util.getComponent('ipt_apctFaxNo2').setValue(faxs[1]);
                    }
                    if (faxs.length > 2) {
                        $c.util.getComponent('ipt_apctFaxNo3').setValue(faxs[2]);
                    }
                }
                if (jsonData.encryp_cellphone_no != null) {
                    const hp = jsonData.encryp_cellphone_no.toString();
                    const hps = hp.split("-");
                    if (hps.length > 0) {
                        $c.util.getComponent('ipt_apctHpNo1').setValue(hps[0]);
                    }
                    if (hps.length > 1) {
                        $c.util.getComponent('ipt_apctHpNo2').setValue(hps[1]);
                    }
                    if (hps.length > 2) {
                        $c.util.getComponent('ipt_apctHpNo3').setValue(hps[2]);
                    }
                }
                if (applId === "" || applId === "undefined") {
                    await $c.win.alert("직전 입력내용이 반영되었습니다.\n\r수정후 신청하시기 바랍니다.");
                } else {
                    await $c.win.alert("기신청한 내용이 반영되었습니다.\n\r수정후 재신청하시기 바랍니다.");
                }
            }
    });
};

/**
 * @method
 * @name chg_group
 * @description chg group 처리
 * @param {*} item item
 * @returns {void}
 * @hidden N
 */
scwin.chg_group = function (item) {
    const temp = $('input[name=group]:checked').val();
    if (temp === 'E') {
        $c.util.getComponent('ipt_cfiCdCategory').setValue("E");
    } else {
        if (temp === 'D') {
            $c.util.getComponent('ipt_cfiCdCategory').setValue("D");
        } else {
            if (temp === 'R') {
                $c.util.getComponent('ipt_cfiCdCategory').setValue("R");
            }
        }
    }
    getCfiCode("JLDINF10700");
    $c.util.getComponent('ipt_cfiCdGroup').setValue(item.getValue());
    scwin.chg_attr();
};

/**
 * @method
 * @name chg_attr
 * @description chg attr 처리
 * @returns {void}
 * @hidden N
 */
scwin.chg_attr = function () {
    $c.util.getComponent('ipt_cfiCd').setValue("");
    $c.util.getComponent('ipt_cfiCd').setValue(($c.util.getComponent("ipt_cfiCdCategory").getValue() || '') + "D" + ($c.util.getComponent("slc_attr01").getValue() || '') + ($c.util.getComponent("slc_attr02").getValue() || '') + ($c.util.getComponent("slc_attr03").getValue() || '') + ($c.util.getComponent("slc_attr04").getValue() || ''));
    $c.util.getComponent('ipt_cfiCdGroup').setValue("D");
    $c.util.getComponent('ipt_cfiCdAttr1').setValue(($c.util.getComponent("slc_attr01").getValue() || ''));
    $c.util.getComponent('ipt_cfiCdAttr2').setValue(($c.util.getComponent("slc_attr02").getValue() || ''));
    $c.util.getComponent('ipt_cfiCdAttr3').setValue(($c.util.getComponent("slc_attr03").getValue() || ''));
    $c.util.getComponent('ipt_cfiCdAttr4').setValue(($c.util.getComponent("slc_attr04").getValue() || ''));
    $c.util.getComponent('ipt_fisnVal').setValue("");
    $c.util.getComponent('ipt_fisnMakeYn').setValue("N");
};

/**
 * @method
 * @name makeFisn
 * @description make Fisn 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.makeFisn = async function () {
    $c.util.getComponent("ipt_comEngAbbrv").setValue(fn_cut_spacingWords($c.util.getComponent('ipt_comEngAbbrv').getValue(), 15));
    const thisForm = $('#JLDINF10700');
    const chkBl = await scwin.dataValidation();
    if (chkBl) {
        return;
    }
    let temp = "";
    temp += $c.util.getComponent('ipt_comEngAbbrv').getValue();
    temp += "/KDR";
    $c.util.getComponent('ipt_fisnVal').setValue(fn_cut_spacingWords(temp, 35));
    $c.util.getComponent('ipt_fisnVal').setValue(($c.util.getComponent("ipt_fisnVal").getValue() || '').toUpperCase());
    $c.util.getComponent('ipt_fisnMakeYn').setValue("Y");
};

/**
 * @method
 * @name checkNumUpperEnglish
 * @description check Num Upper English 처리
 * @param {*} aObj aObj
 * @param {*} aDesc aDesc
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkNumUpperEnglish = async function (aObj, aDesc) {
    const val = aObj.value;
    const len = val.length;
    for (let i = 0; i < len; i++) {
        const ch = val.charAt(i);
        const isNumEnglish = (ch >= '0' && ch <= '9') || (ch >= 'A' && ch <= 'Z');
        if (!isNumEnglish) {
            await $c.win.alert(aDesc + " - " + "숫자나 영문 대문자만 입력하십시오.");
            setTimeout(function() {
                    $("#glbl_isin_cd").select();
                }, 10);
            return false;
        }
    }
    return true;
};

/**
 * @method
 * @name chk_chrg_nm
 * @description chk chrg nm 처리
 * @param {*} fm fm
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.chk_chrg_nm = async function (fm) {
    const len = $c.str.getByteLength(fm.chrg_nm.value);
    if (len > 20) {
        await $c.win.alert("이름은 한글10자, 영문20자 이내로 입력하세요.");
        chrg_nm.focus();
        return;
    }
};
